    if (char === "." && !seenDot) {
      seenDot = true;
      index += 1;
      continue;
    }
    return false;
  }

  return seenDigit;
}

function blocksOptionValue(token) {
  if (token === undefined) {
    return true;
  }
  if (token === "-h" || token === "--help" || token === "--a" || token.startsWith("--a=")) {
    return true;
  }
  if (token.startsWith("--")) {
    return token.length > 2 && token[2] !== "-";
  }
  if (token.startsWith("-")) {
    if (token.length === 1) {
      return false;
    }
    const next = token[1];
    if (next === " " || next === "\t" || next === "\n" || next === "\r") {
      return false;
    }
    return !isNegativeNumberToken(token);
  }
  return false;
}

export function parseCommandLine(argv) {
  const programName = "test15_executable";

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    if (token === "-h" || token === "--help") {
      return { kind: "help", text: buildHelp(programName) };
    }
  }

  let value = null;
  let hasValue = false;
  let missingValue = false;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "--a") {
      const next = argv[index + 1];
      if (blocksOptionValue(next)) {
        missingValue = true;
        break;
      }
      value = next;
      hasValue = true;
      index += 1;
      continue;
    }

    if (token.startsWith("--a=")) {
      value = token.slice(4);
      hasValue = true;
      continue;
    }

    extras.push(token);
  }

  if (missingValue) {
    return {
      kind: "error",
      exitCode: 2,
      text: buildError(programName, "argument --a: expected one argument"),
    };
  }

  if (!hasValue) {
    return {
      kind: "error",
      exitCode: 2,
      text: buildError(programName, "the following arguments are required: --a"),
    };
  }

  if (extras.length > 0) {
    return {
      kind: "error",
      exitCode: 2,
      text: buildError(programName, formatUnrecognized(extras)),
    };
  }

  return { kind: "run", a: value };
}

import { parseCommandLine } from "./lib/cli.mjs";
import { transformYaml } from "./lib/yaml/index.mjs";

const parsed = parseCommandLine(process.argv.slice(2));

if (parsed.kind === "help") {
  process.stdout.write(parsed.text);
  process.exit(0);
}

if (parsed.kind === "error") {
  process.stderr.write(parsed.text);
  process.exit(parsed.exitCode);
}

const result = transformYaml(parsed.a);
process.stdout.write(result);
process.stdout.write("\n");

